// Command chart writes the generated files of the Helm chart. config stays
// the one source, so nobody edits those files by hand. Run it from the root
// of the repository through make chart.
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"

	utilyaml "k8s.io/apimachinery/pkg/util/yaml"
	"sigs.k8s.io/yaml"
)

const (
	configDefault = "config/default"
	crdBases      = "config/crd/bases"
	crdsDir       = "helm/fiberd-k8s-controller/crds"
	generatedDir  = "helm/fiberd-k8s-controller/templates/generated"

	header = "# Generated by make chart from config. Do not edit.\n"

	namespaceTemplate = "{{.Values.certManager.namespace}}"
	subjectPrefix     = "system:serviceaccount:"
)

// substitution turns one default string of config into a template. An exact
// row replaces a whole value, and any other row replaces inside a value. A
// required row must match, so a renamed default fails here instead of
// reaching the chart.
//
// Templates other than the image hold no spaces, so the YAML writer can never
// fold a long line inside one.
type substitution struct {
	old      string
	template string
	exact    bool
	required bool
}

// substitutions is ordered. The csi-driver row comes first because the row
// after it matches a prefix of the same string.
var substitutions = []substitution{
	{
		old:      "controller:latest",
		template: `{{include "fiberd-k8s-controller.image" .}}`,
		exact:    true,
		required: true,
	},
	{
		old:      "cert-manager",
		template: namespaceTemplate,
		exact:    true,
		required: true,
	},
	{
		old:      subjectPrefix + "cert-manager:cert-manager-csi-driver",
		template: subjectPrefix + namespaceTemplate + ":{{.Values.certManager.csiDriverServiceAccount}}",
	},
	{
		old:      subjectPrefix + "cert-manager:cert-manager",
		template: subjectPrefix + namespaceTemplate + ":{{.Values.certManager.serviceAccount}}",
	},
}

func main() {
	kustomize := flag.String("kustomize", "", "the command that runs the pinned kustomize")
	flag.Parse()
	if err := run(strings.Fields(*kustomize)); err != nil {
		fmt.Fprintln(os.Stderr, "chart:", err)
		os.Exit(1)
	}
}

// run reads everything before it writes anything, so a failure leaves the
// chart as it was.
func run(kustomize []string) error {
	if len(kustomize) == 0 {
		return errors.New("-kustomize is required")
	}
	build, err := kustomizeBuild(kustomize)
	if err != nil {
		return fmt.Errorf("building %s: %w", configDefault, err)
	}
	templates, err := render(build, substitutions)
	if err != nil {
		return err
	}
	crds, err := readYAMLFiles(crdBases)
	if err != nil {
		return err
	}
	if err := replaceDir(generatedDir, templates); err != nil {
		return err
	}
	return replaceDir(crdsDir, crds)
}

func kustomizeBuild(kustomize []string) ([]byte, error) {
	args := slices.Concat(kustomize[1:], []string{"build", configDefault})
	cmd := exec.Command(kustomize[0], args...)
	cmd.Stderr = os.Stderr
	return cmd.Output()
}

// render turns a kustomize build into the generated templates, keyed by file
// name. Parsing drops comments, and the writer sorts keys, so the same objects
// always give the same bytes.
func render(build []byte, subs []substitution) (map[string][]byte, error) {
	objects, err := decode(build)
	if err != nil {
		return nil, err
	}
	files := make(map[string][]byte, len(objects))
	matched := make([]bool, len(subs))
	for _, obj := range objects {
		if leftOut(obj) {
			continue
		}
		name, err := fileName(obj)
		if err != nil {
			return nil, err
		}
		if _, ok := files[name]; ok {
			return nil, fmt.Errorf("two objects would share the file %s", name)
		}
		if err := refuseTemplates(name, obj); err != nil {
			return nil, err
		}
		data, err := yaml.Marshal(walk(obj, func(value string) string {
			return substitute(value, subs, matched)
		}))
		if err != nil {
			return nil, fmt.Errorf("writing %s: %w", name, err)
		}
		files[name] = append([]byte(header), data...)
	}
	for i, sub := range subs {
		if sub.required && !matched[i] {
			return nil, fmt.Errorf("no object holds %q", sub.old)
		}
	}
	return files, nil
}

func decode(build []byte) ([]map[string]any, error) {
	decoder := utilyaml.NewYAMLToJSONDecoder(bytes.NewReader(build))
	var objects []map[string]any
	for {
		var obj map[string]any
		err := decoder.Decode(&obj)
		if errors.Is(err, io.EOF) {
			return objects, nil
		}
		if err != nil {
			return nil, fmt.Errorf("parsing the build: %w", err)
		}
		if obj != nil {
			objects = append(objects, obj)
		}
	}
}

// leftOut reports an object the templates do not carry. Helm creates the
// namespace, and crds/ carries the CRDs.
func leftOut(obj map[string]any) bool {
	kind := obj["kind"]
	return kind == "Namespace" || kind == "CustomResourceDefinition"
}

func fileName(obj map[string]any) (string, error) {
	kind, _ := obj["kind"].(string)
	metadata, _ := obj["metadata"].(map[string]any)
	name, _ := metadata["name"].(string)
	if kind == "" || name == "" {
		return "", fmt.Errorf("an object has no kind or name, %v", obj)
	}
	return strings.ToLower(kind) + "-" + name + ".yaml", nil
}

// refuseTemplates stops source text that Helm would run as a template. JSON
// never places two opening braces together on its own, so a hit is always
// inside a key or a value.
func refuseTemplates(name string, obj map[string]any) error {
	data, err := json.Marshal(obj)
	if err != nil {
		return fmt.Errorf("reading %s: %w", name, err)
	}
	if bytes.Contains(data, []byte("{{")) {
		return fmt.Errorf("%s holds {{, which Helm would run as a template", name)
	}
	return nil
}

func walk(value any, visit func(string) string) any {
	switch v := value.(type) {
	case string:
		return visit(v)
	case []any:
		out := make([]any, len(v))
		for i, item := range v {
			out[i] = walk(item, visit)
		}
		return out
	case map[string]any:
		out := make(map[string]any, len(v))
		for key, item := range v {
			out[key] = walk(item, visit)
		}
		return out
	default:
		return value
	}
}

// substitute applies each row in order and records the rows that matched.
func substitute(value string, subs []substitution, matched []bool) string {
	for i, sub := range subs {
		switch {
		case sub.exact && value == sub.old:
			matched[i] = true
			return sub.template
		case !sub.exact && strings.Contains(value, sub.old):
			matched[i] = true
			value = strings.ReplaceAll(value, sub.old, sub.template)
		}
	}
	return value
}

func readYAMLFiles(dir string) (map[string][]byte, error) {
	paths, err := filepath.Glob(filepath.Join(dir, "*.yaml"))
	if err != nil {
		return nil, err
	}
	if len(paths) == 0 {
		return nil, fmt.Errorf("%s holds no YAML files", dir)
	}
	files := make(map[string][]byte, len(paths))
	for _, path := range paths {
		data, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		files[filepath.Base(path)] = data
	}
	return files, nil
}

// replaceDir starts from an empty directory, so an object removed from config
// leaves no stale file behind.
func replaceDir(dir string, files map[string][]byte) error {
	if err := os.RemoveAll(dir); err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	for name, data := range files {
		if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil {
			return err
		}
	}
	return nil
}
